(2428523, 333630, 41574, '<td valign="top">You know, when I read the title of the challenge (last week), I expected to be rating dozens of black shots. Apparently, this is the only one that''s been entered (or, I haven''t yet stumbled across any others [I''ve been through many, though]). I wan''t to give you either a "10" for having balls, or a "1" for being lazy and clichéd (and trying to get away with being so). I see noise, so I think you actually did take the shot, and not just make this in Microsoft Paint...FINE: "10"!</td>', 'You know, when I read the title of the challenge (last week), I expected to be rating dozens of black shots. Apparently, this is the only one that''s been entered (or, I haven''t yet stumbled across any others [I''ve been through many, though]). I wan''t to give you either a "10" for having balls, or a "1" for being lazy and clichéd (and trying to get away with being so). I see noise, so I think you actually did take the shot, and not just make this in Microsoft Paint...FINE: "10"!', '2006-05-18 02:23:58.000000', NULL, 1),
(2428525, 335361, 41574, '<td valign="top">Absolutely dull, uninteresting shot. Too small, too.</td>', 'Absolutely dull, uninteresting shot. Too small, too.', '2006-05-18 02:24:29.000000', NULL, 1),
(2428533, 334315, 41574, '<td valign="top">Kick-ass (cool). My second (or third) "10" thus far (and I''ve been through many). Good job. I love that the photo is <b>both</b> technically sound, and chellenge-meeting.</td>', 'Kick-ass (cool). My second (or third) "10" thus far (and I''ve been through many). Good job. I love that the photo is both technically sound, and chellenge-meeting.', '2006-05-18 02:26:33.000000', NULL, 1),
(2428541, 335172, 41574, '<td valign="top">I get it: You want to see if you can be infamous for submitting the worst photograph in the history of Dpchallenge. I don''t know whether you can or can''t, but it''s clear that you''ve put in a lot of effort in trying to do so. I''m not even going to say anything to the effect of "sorry if you really were trying," because this photo CANNOT be the product of "trying." I''d like to give you a "10" just for the hell of it, but...I can''t. Congratulations, on what might be the worst job ever. (I love that you didn''t just submit a technically atrocious photograph, but one that doesn''t seem to have a "lens cap" [that is, one that doesn''t "meet the challenge"], either. Again, bravo.)</td>', 'I get it: You want to see if you can be infamous for submitting the worst photograph in the history of Dpchallenge. I don''t know whether you can or can''t, but it''s clear that you''ve put in a lot of effort in trying to do so. I''m not even going to say anything to the effect of "sorry if you really were trying," because this photo CANNOT be the product of "trying." I''d like to give you a "10" just for the hell of it, but...I can''t. Congratulations, on what might be the worst job ever. (I love that you didn''t just submit a technically atrocious photograph, but one that doesn''t seem to have a "lens cap" [that is, one that doesn''t "meet the challenge"], either. Again, bravo.)', '2006-05-18 02:29:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2428544, 335441, 41574, '<td valign="top">I think it might have been better if you''d shown us more of (what I can only deduce must be) the tic-tac-toe board. It''s a nice idea, but it could have been better executed.</td>', 'I think it might have been better if you''d shown us more of (what I can only deduce must be) the tic-tac-toe board. It''s a nice idea, but it could have been better executed.', '2006-05-18 02:30:11.000000', NULL, 1),
(2428548, 335576, 41574, '<td valign="top">If this is "real," it''s awesome. Great work.</td>', 'If this is "real," it''s awesome. Great work.', '2006-05-18 02:32:01.000000', NULL, 1),
(2428549, 334276, 49858, '<td valign="top">Nice idea, but would have worked better with a plain white background.</td>', 'Nice idea, but would have worked better with a plain white background.', '2006-05-18 02:32:16.000000', NULL, 1),
(2428552, 332528, 41574, '<td valign="top">This is the second black image that I''ve run across. The first one got a "10," so, naturally, yours gets a "1." Hell, at least the first had some noice, indicating that it was a "real" photograph. I put your into my photo-editing software, and pumped up the brightness all the way: perfect gray. What did you do, make this in Microsoft Paint?</td>', 'This is the second black image that I''ve run across. The first one got a "10," so, naturally, yours gets a "1." Hell, at least the first had some noice, indicating that it was a "real" photograph. I put your into my photo-editing software, and pumped up the brightness all the way: perfect gray. What did you do, make this in Microsoft Paint?', '2006-05-18 02:33:51.000000', NULL, 1),
(2428557, 332542, 41574, '<td valign="top">Maybe I just suck (really, that might be the case), but I don''t see any lens cap.</td>', 'Maybe I just suck (really, that might be the case), but I don''t see any lens cap.', '2006-05-18 02:34:29.000000', NULL, 1),
(2428562, 332866, 41574, '<td valign="top">I don''t see it: where the hell is the lens cap? Sorry if I''m just missing it, but you get a "1" (maybe you meant to submit this to the "Member Challenge," "Environmental Portrait").</td>', 'I don''t see it: where the hell is the lens cap? Sorry if I''m just missing it, but you get a "1" (maybe you meant to submit this to the "Member Challenge," "Environmental Portrait").', '2006-05-18 02:36:33.000000', NULL, 1),
(2428564, 335348, 41574, '<td valign="top">A very uninspired shot. It''s as though you read the title of the challenge, and took the easiest shot you possibly could, that was in accordance with its guidelines. Next time, try harder.</td>', 'A very uninspired shot. It''s as though you read the title of the challenge, and took the easiest shot you possibly could, that was in accordance with its guidelines. Next time, try harder.', '2006-05-18 02:38:17.000000', NULL, 1),
(2428674, 332641, 48967, '<td valign="top">a little different from what i''ve seen... hehehe</td>', 'a little different from what i''ve seen... hehehe', '2006-05-18 03:26:50.000000', NULL, 1),
