(2430394, 333838, 37444, '<td valign="top">Nicely done - 8</td>', 'Nicely done - 8', '2006-05-18 14:46:27.000000', NULL, 1),
(2430397, 335354, 37444, '<td valign="top">Go Canon! LOL</td>', 'Go Canon! LOL', '2006-05-18 14:46:49.000000', NULL, 1),
(2430400, 333522, 30893, '<td valign="top">Points for creativity. The grass(?) in the foreground is a little distracting.</td>', 'Points for creativity. The grass(?) in the foreground is a little distracting.', '2006-05-18 14:46:56.000000', NULL, 1),
