(2431498, 332569, 56673, '<td valign="top">The fact that the only visible words are very blurry detracts from the shot, as it is distracting.  Because of the general lack of detail elsewhere, they eye is drawn to the blur.</td>', 'The fact that the only visible words are very blurry detracts from the shot, as it is distracting.  Because of the general lack of detail elsewhere, they eye is drawn to the blur.', '2006-05-18 20:18:19.000000', NULL, 1),
(2431501, 334977, 52957, '<td valign="top">very funny, good shot</td>', 'very funny, good shot', '2006-05-18 20:19:15.000000', NULL, 1),
(2431503, 335501, 52957, '<td valign="top">so cute !!!</td>', 'so cute !!!', '2006-05-18 20:19:38.000000', NULL, 1),
(2431504, 335392, 56673, '<td valign="top">Okay, giving up your lens cap to a baboon is going above and beyond the call of duty.  I hope he (she?) didn''t swallow it!</td>', 'Okay, giving up your lens cap to a baboon is going above and beyond the call of duty.  I hope he (she?) didn''t swallow it!', '2006-05-18 20:19:45.000000', NULL, 1),
(2431506, 335172, 56673, '<td valign="top">Ummm, that''s really small and blurry, and I don''t see any lens caps.</td>', 'Ummm, that''s really small and blurry, and I don''t see any lens caps.', '2006-05-18 20:20:35.000000', NULL, 1),
(2431510, 334509, 52957, '<td valign="top">that is so cool it deserves a 10</td>', 'that is so cool it deserves a 10', '2006-05-18 20:21:49.000000', NULL, 1),
(2431517, 333887, 56673, '<td valign="top">Very well done.  Clever conversion of the caps into bugs, and funny commentary on previous DPC submissions.</td>', 'Very well done.  Clever conversion of the caps into bugs, and funny commentary on previous DPC submissions.', '2006-05-18 20:24:32.000000', NULL, 1),
(2431526, 335601, 56673, '<td valign="top">Really good idea.  The lighting is a little off (camera in too much shadow).</td>', 'Really good idea.  The lighting is a little off (camera in too much shadow).', '2006-05-18 20:26:42.000000', NULL, 1),
(2431529, 334827, 56673, '<td valign="top">Very cool picture!  Love the use of the open aperture!</td>', 'Very cool picture!  Love the use of the open aperture!', '2006-05-18 20:27:48.000000', NULL, 1),
(2431536, 332641, 56673, '<td valign="top">Makes me wonder where that camera has been!</td>', 'Makes me wonder where that camera has been!', '2006-05-18 20:29:31.000000', NULL, 1),
(2431538, 334904, 56673, '<td valign="top">Not the only cookie shot, but certainly one of the best executed cookie shots.  Nice set-up!</td>', 'Not the only cookie shot, but certainly one of the best executed cookie shots.  Nice set-up!', '2006-05-18 20:30:26.000000', NULL, 1),
(2431545, 335576, 56673, '<td valign="top">Neat effect.  Good color and texture.</td>', 'Neat effect.  Good color and texture.', '2006-05-18 20:31:59.000000', NULL, 1),
(2431548, 334439, 41574, '<td valign="top">It doesn''t meet the challenge too well, but it''s such a great "bug shot," that I can''t give it too low a score.</td>', 'It doesn''t meet the challenge too well, but it''s such a great "bug shot," that I can''t give it too low a score.', '2006-05-18 20:33:10.000000', NULL, 1),
(2431551, 335130, 41574, '<td valign="top">Where''s the lens cap?</td>', 'Where''s the lens cap?', '2006-05-18 20:34:11.000000', NULL, 1),
(2431553, 335051, 34396, '<td valign="top">An old idea here, but it always seems to work.  I really like the color choice of the background.  The different sizes of all of the images are very nice!</td>', 'An old idea here, but it always seems to work.  I really like the color choice of the background.  The different sizes of all of the images are very nice!', '2006-05-18 20:34:31.000000', NULL, 1),
(2431554, 334392, 41574, '<td valign="top">Very creative; great colors: good job.</td>', 'Very creative; great colors: good job.', '2006-05-18 20:34:38.000000', NULL, 1),
(2431557, 335425, 56673, '<td valign="top">Very good concept, and well executed!  I don''t see any string, so I''m anxious to read how you stopped this action.</td>', 'Very good concept, and well executed!  I don''t see any string, so I''m anxious to read how you stopped this action.', '2006-05-18 20:35:20.000000', NULL, 1),
(2431560, 334700, 56673, '<td valign="top">I''m glad someone used this idea.  It was one I thought of, but you did it better than I would have.</td>', 'I''m glad someone used this idea.  It was one I thought of, but you did it better than I would have.', '2006-05-18 20:36:04.000000', NULL, 1),
(2431564, 335388, 41574, '<td valign="top">I''ve seen a few "pirates" at this point, but this one (this shot) stands out. Great job.</td>', 'I''ve seen a few "pirates" at this point, but this one (this shot) stands out. Great job.', '2006-05-18 20:36:11.000000', NULL, 1);
