(2434181, 332798, 13759, '<td valign="top">Creative. I don´t like so much of your light source. It makes much glares and reflections. I was well reflected to fill the subject but not so much difuset to be used in glass/reflective surfaces.</td>', 'Creative. I don´t like so much of your light source. It makes much glares and reflections. I was well reflected to fill the subject but not so much difuset to be used in glass/reflective surfaces.', '2006-05-19 07:37:39.000000', NULL, 1),
(2434187, 332710, 13759, '<td valign="top">Oh no! Where are the lens cap? Did you left in home? Sorry DNMC.</td>', 'Oh no! Where are the lens cap? Did you left in home? Sorry DNMC.', '2006-05-19 07:39:52.000000', NULL, 1),
(2434191, 335182, 13759, '<td valign="top">A bit dark to me.</td>', 'A bit dark to me.', '2006-05-19 07:40:15.000000', NULL, 1),
(2434201, 334994, 13759, '<td valign="top">Good idea! The execution was not so impressive due to the light. In verry reflective subjects like this you may need to difuse a lot you light source. Try to use a thin white nylon or difusers made for photography. The key for good ligh is to think that a good light source is big. That stands that the source must be in some way large relative to the subject, this improve difusion.</td>', 'Good idea! The execution was not so impressive due to the light. In verry reflective subjects like this you may need to difuse a lot you light source. Try to use a thin white nylon or difusers made for photography. The key for good ligh is to think that a good light source is big. That stands that the source must be in some way large relative to the subject, this improve difusion.', '2006-05-19 07:45:26.000000', NULL, 1),
(2434204, 332528, 13759, '<td valign="top">Ah, I can see!</td>', 'Ah, I can see!', '2006-05-19 07:46:21.000000', NULL, 1),
