(2441572, 335348, 55746, '<td valign="top">I feel like the focus should be on the name on the lens cap but it is on the back side of the cap.</td>', 'I feel like the focus should be on the name on the lens cap but it is on the back side of the cap.', '2006-05-20 22:17:47.000000', NULL, 1),
(2441573, 334340, 55746, '<td valign="top">Great photo!  I find the leaf of the flower a bit distracting but otherwise this is great.  10</td>', 'Great photo!  I find the leaf of the flower a bit distracting but otherwise this is great.  10', '2006-05-20 22:18:48.000000', NULL, 1),
(2441574, 333385, 55746, '<td valign="top">I like your idea but I don''t see a lens cap.</td>', 'I like your idea but I don''t see a lens cap.', '2006-05-20 22:19:27.000000', NULL, 1),
(2441575, 334994, 8624, '<td valign="top">I like this idea a *lot*, but I think you could have improved the execution. the shadows are harsh and focus is soft. a more interesting background and lighting could have made this shot a real contender.</td>', 'I like this idea a *lot*, but I think you could have improved the execution. the shadows are harsh and focus is soft. a more interesting background and lighting could have made this shot a real contender.', '2006-05-20 22:20:04.000000', NULL, 1),
