INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2444129, 334863, 11518, '<td valign="top">ROFLMAO  Good one!</td>', 'ROFLMAO  Good one!', '2006-05-21 21:16:51.000000', NULL, 1),
(2444143, 333440, 30982, '<td valign="top">Very nice idea for the challenge and lighting is spot on.</td>', 'Very nice idea for the challenge and lighting is spot on.', '2006-05-21 21:21:58.000000', NULL, 1),
(2444146, 335372, 30982, '<td valign="top">Nice humorous take on the challenge, and pretty interesting picture on its own.  Like the leading line.</td>', 'Nice humorous take on the challenge, and pretty interesting picture on its own.  Like the leading line.', '2006-05-21 21:23:34.000000', NULL, 1),
(2444148, 335053, 30982, '<td valign="top">The hand reaching through the frame is interesting and effective.  The loss of focus on the frame just above the milk detracts a bit.</td>', 'The hand reaching through the frame is interesting and effective.  The loss of focus on the frame just above the milk detracts a bit.', '2006-05-21 21:24:27.000000', NULL, 1),
(2444151, 335047, 30982, '<td valign="top">Nice crisp, desolate picture - hope you took one without the lens cap, too.  Only nit is the cap appears to be just set into the photo to meet the challenge.</td>', 'Nice crisp, desolate picture - hope you took one without the lens cap, too.  Only nit is the cap appears to be just set into the photo to meet the challenge.', '2006-05-21 21:25:41.000000', NULL, 1),
(2444156, 335382, 30982, '<td valign="top">Angle adds interest to what is a somewhat common theme in this challenge.  Good exposure in both the blacks and the whites although there appears to be a bluish tint in the whites.</td>', 'Angle adds interest to what is a somewhat common theme in this challenge.  Good exposure in both the blacks and the whites although there appears to be a bluish tint in the whites.', '2006-05-21 21:27:02.000000', NULL, 1),
(2444161, 334315, 52500, '<td valign="top">It''s amazing how you set the tone and mood in this picture even though you can''t see his eyes.  That shows talent to me!</td>', 'It''s amazing how you set the tone and mood in this picture even though you can''t see his eyes.  That shows talent to me!', '2006-05-21 21:27:59.000000', NULL, 1),
(2444164, 332641, 30982, '<td valign="top">Good lighting for this shot.  What kind of effect does this particular "filter" produce, I wonder?</td>', 'Good lighting for this shot.  What kind of effect does this particular "filter" produce, I wonder?', '2006-05-21 21:28:21.000000', NULL, 1),
(2444167, 335584, 30982, '<td valign="top">Only nit here is need a bit better lighting on the card faces.  Good DOF.</td>', 'Only nit here is need a bit better lighting on the card faces.  Good DOF.', '2006-05-21 21:28:50.000000', NULL, 1),
(2444170, 333646, 30982, '<td valign="top">Nice background for a shot of a lens cap.</td>', 'Nice background for a shot of a lens cap.', '2006-05-21 21:29:15.000000', NULL, 1),
(2444173, 335425, 52500, '<td valign="top">Great composition, Super sharp, love the contrast.  The floating lens cap is very believable.</td>', 'Great composition, Super sharp, love the contrast.  The floating lens cap is very believable.', '2006-05-21 21:29:31.000000', NULL, 1),
(2444178, 333838, 52500, '<td valign="top">I like how super sharp this is, and the use of colors.  Vibrant and well done!</td>', 'I like how super sharp this is, and the use of colors.  Vibrant and well done!', '2006-05-21 21:30:30.000000', NULL, 1),
(2444179, 335599, 30982, '<td valign="top">I''m guessing this is a set up with a monitor?  If not, nice job of suspending the cap!  Interesting take on the challenge, too.</td>', 'I''m guessing this is a set up with a monitor?  If not, nice job of suspending the cap!  Interesting take on the challenge, too.', '2006-05-21 21:30:34.000000', NULL, 1),
(2444180, 333022, 52500, '<td valign="top">This was very well thought out and extremely well executed.  I love the use of peanuts!  Nice job, very original.</td>', 'This was very well thought out and extremely well executed.  I love the use of peanuts!  Nice job, very original.', '2006-05-21 21:30:39.000000', NULL, 1),
(2444181, 334309, 30982, '<td valign="top">Like the use of texture and color here - works very well.</td>', 'Like the use of texture and color here - works very well.', '2006-05-21 21:30:49.000000', NULL, 1),
(2444185, 334392, 52500, '<td valign="top">This is very well done and the funniest lens cap in the whole bunch!  I laugh every time I look at it.</td>', 'This is very well done and the funniest lens cap in the whole bunch!  I laugh every time I look at it.', '2006-05-21 21:31:19.000000', NULL, 1),
